from pathlib import Path
import json
D=Path(__file__).resolve().parent
def get(k):return json.loads((D/k).read_bytes())
def f(x):return f'{x:,.2f}'.replace(',',' ').replace('.',',')
def u(n):return f'{int(n):,}'.replace(',',' ')
def effect(c):
    return f(100*c['saving'])+'% ['+f(100*c['ci'][0])+'%; '+f(100*c['ci'][1])+'%]'
def main():
    r=get('results.json');hrs=get('heap.json');t=r['totals'];p=r['contrasts']['proposed vs lru'];g=r['contrasts']['proposed vs gdsf'];fresh=t['fresh'];candidates=r['documents']
    allpos=all(e['wall_rank']['ci'][0]>0 for e in (p,g));verdict=('Предопределённый критерий ускорения относительно обоих контролей выполнен.' if allpos else 'Предопределённый критерий ускорения относительно обоих контролей не выполнен.')
    periods=['| Физический режим | Время до полного ранга, с | С записью, с | Занятость GPU, engine-с | Вызовы эмбеддинга, wall с | Кодировано токенов | MSS@5 / MSS@8, из 24 |',
             '|---|---:|---:|---:|---:|---:|---:|']
    for k,label in [('fresh','Новая обработка каждого фрагмента'),('lru','Пакетный hot-LRU с приоритетом дорогих входов'),('gdsf','Пакетный GDSF со старением'),('proposed','Сглаженная частота × стоимость')]:
        a=t[k];periods.append(f"| {label} | {f(a['wall_rank'])} | {f(a['wall_commit'])} | {f(a['compute_engine_s'])} | {f(a['rpc_wall'])} | {u(a['tokens'])} | {r['mss'][k+':mss5']} / {r['mss'][k+':mss8']} |")
    detail=['| Репозиторий | Политика, с | Сильный LRU, с | Пакетный GDSF, с |','|---|---:|---:|---:|']
    for repo,v in r['chain_totals'].items():detail.append(f"| {repo} | {f(v['proposed']['wall_rank'])} | {f(v['lru']['wall_rank'])} | {f(v['gdsf']['wall_rank'])} |")
    q=r['quality'];mx=r['max_score_error'];vmax=max(hrs['max'].values());heap_ok=vmax<=hrs['cap']
    paras=[f"**{verdict}** На восьми новых репозиториях экономия сквозного времени политики «частота × стоимость» относительно усиленного стоимостного LRU составила **{effect(p['wall_rank'])}**, относительно пакетного GDSF — **{effect(g['wall_rank'])}**. Положительное значение означает ускорение. Из восьми цепочек ускорение наблюдалось соответственно на {p['wall_rank']['wins']} и {g['wall_rank']['wins']}. На каждой цепочке измерены все четыре режима с холодным началом пользовательского кеша. [Протокол](PROTOCOL_RU.md) · [Все парные оценки](results.json)",
        "Из 179 состояний прежней train-части SERBench нашлись 25 полных строгих цепочек минимум с тремя доступными состояниями из 23 разных репозиториев. Восемь цепочек отобраны по хешу до вычисления их расходов и времени, максимум одна на репозиторий. Все выбранные содержали по три снимка одного запуска, вместе 24 состояния. Эта панель не пересекается с 305 состояниями, на которых разрабатывался кеш R48, включая прежние восемь двухшаговых аппаратных пар. Ранее те же 179 состояний использовали для обучения другой модели поиска. Модель — Qwen3-Embedding-8B Q4_K_M, кодировщику подавалось до 512 токенов на фрагмент, GPU — RTX 3090. [Критерии и список всех пригодных цепочек](panel.json)",
        '\n'.join(periods),
        f"На этих же трассах различие по входным токенам относительно усиленного LRU составило {effect(p['tokens'])}, относительно пакетного GDSF — {effect(g['tokens'])}. Отдельный счётчик накопленного времени CUDA-движков процесса показывает {effect(p['compute_engine_s'])} и {effect(g['compute_engine_s'])} экономии. Время до выдачи измерено от исходных строк на входе, включая подготовку кандидатов, локальную токенизацию, ключи, получение/копирование векторов, вызовы кодировщика и сортировку. Загрузка модели и чтение набора с диска за пределами запроса исключены. Столбец «С записью» включает время обновления постоянного кеша после получения ранга. Для каждого из 96 запросов отдельно зарегистрирована положительная аппаратная активность CUDA процесса. [Полные квитанции аппаратного стенда](raw-runs.json.gz)",
        '\n'.join(detail),
        f"В трёх режимах с кешем кодировались только уникальные документы, отсутствующие среди сохранённых векторов. Контроль свежего кодирования отдельно обрабатывал каждое вхождение. Сравнение с независимой свежей обработкой проверило для исследуемой политики {u(q['proposed:vectors'])} векторов запросов и источников. Побитовое совпадение обнаружено у {u(q['proposed:exact'])}, полный порядок совпал в {q['proposed:fullorder']}/24 состояниях. Максимальное абсолютное отклонение оценки косинусной близости {mx['proposed']:.3g}. Результаты по каждому режиму сохранены вместе с хешами векторов, метриками официального оценщика и расходами. [Проверка рангов и сертификатов](quality.json.gz)",
        f"Бюджет ограничивает сохраняемые между запросами ключи и векторы. Каждый слот хранит 16 384 байта float32-значений, на метаданные в расчётной схеме отведено 64 байта на слот, 256 байт на заголовок, 1 024 байта на эскиз. Максимум 31 действительный вектор. При отдельном воспроизведении живых объектов Python на этих же ключах наибольший размер состояния после записи по getsizeof равнялся {u(vmax)} байтам при пределе 524 288 ({'в пределах лимита' if heap_ok else 'превышение логического лимита реализацией стенда'}). Время и память текущего временного пакета относятся к рабочей области, которая одинакова для алгоритмов. [Аудит постоянных объектов](heap.json)",
        "Единица неопределённости — репозиторий, число независимых единиц восемь. Режимы сбалансированы по позиции и соседству, но каждое сочетание цепочки и режима измерено один раз. Доверительные интервалы отражают разброс выбранных цепочек; они не оценивают воспроизводимость секунд на других видеокартах или при изменении нагрузки. При равных расходах в токенах различия времени могут возникать из формы CUDA-пакетов, токенизации и шума планирования. Этот опыт измеряет чтение памяти из заданного пула, а не успех решения issue. [Репликация аппаратного измерения](REPRODUCE_RU.md) · [Предыдущее сравнение по токенам](../../graph_memory_round48/cache_admission/REPORT_RU.md)"]
    tr=get('transfer-results.json')['panels'];tt=tr['all'];lo=tt['contrasts']['lru'];gd=tt['contrasts']['gdsf'];st=get('stage-results.json')['stages'];last=st['3'];c=last['contrast']
    def pp(z):return f(100*z['delta'])+' п.п. ['+f(100*z['ci'][0])+'; '+f(100*z['ci'][1])+']'
    paras.insert(5,f"На третьем шаге каждой физической цепочки уже доступны результаты двух прежних запросов. Здесь отдельно измеренная суммарная экономия входных токенов составила {effect(c['lru']['tokens'])} против LRU и {effect(c['gdsf']['tokens'])} против GDSF. Сквозное время на третьем шаге составило {f(last['sums']['proposed']['wall_rank'])}, {f(last['sums']['lru']['wall_rank'])} и {f(last['sums']['gdsf']['wall_rank'])} с соответственно. Разрез вторичный. [Три стадии по состояниям](stage-results.json) · [Дополнительный план](STAGES_RU.md)")
    paras.insert(-1,f"**Отдельный перенос по токенам.** На всех 179 новых состояниях из 68 репозиториев суммарный вход до дедупликации — {u(tt['total'])} токенов. Удаление повторов внутри отдельных запросов дало {u(tt['within'])} токенов. Дополнительно между запросами политика сэкономила {u(tt['arms']['proposed']['inter'])} токенов, усиленный LRU — {u(tt['arms']['lru']['inter'])}, пакетный GDSF — {u(tt['arms']['gdsf']['inter'])}. Преимущество в доле исходного входа {pp(lo)} и {pp(gd)} соответственно. По оставшимся 155 состояниям вне аппаратной подвыборки оценки составляют {pp(tr['not_hardware']['contrasts']['lru'])} и {pp(tr['not_hardware']['contrasts']['gdsf'])}. Все 68 репозиториев отделены от 103 репозиториев R48. Среди репозиториев 155 оставшихся состояний семь также представлены в аппаратной серии. Числовой replay воспроизвёл физические счётчики всех 72 ограниченных выдач на подвыборке; для остальных физических секунд нет. [Протокол переноса](TRANSFER_RU.md) · [Отдельная таблица токенов](transfer-results.json) · [Пересечения панелей](split-audit.json)")
    one=tr['one'];two=tr['two_plus'];cold=tr['cold']
    paras.insert(-1,f"Из {cold['states']} состояний без предшественника ни одна политика не получила межзапросного выигрыша. На {one['states']} состояниях с одним предшественником исследуемая политика обработала на {u(-one['contrasts']['lru']['delta_tokens'])} токенов больше усиленного LRU. На {two['states']} состояниях с двумя или более предшественниками она сэкономила {u(two['contrasts']['lru']['delta_tokens'])} токенов относительно LRU и {u(two['contrasts']['gdsf']['delta_tokens'])} относительно GDSF. Срезы объясняют, откуда взялась суммарная разница в пределах этой выборки. [Разбиение по глубине и неопределённость](transfer-results.json)")
    (D/'REPORT_RU.md').write_text('# Ускоряет ли выбор сохраняемых векторов реальную выдачу на новых траекториях\n\n'+'\n\n'.join(paras)+'\n',encoding='utf8')
if __name__=='__main__':main()

